content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --secondary-color: #475569;
  --secondary-hover: #334155;
  --secondary-bg: #f1f5f9;
  --target-color: #f59e0b;
  --success-color: #10b981;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アプリケーション全体コンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 64px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダーエリア */
.header {
  text-align: left;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 16px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 4px;
}

/* サマリーカードエリア */
.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.summary-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.summary-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.summary-card-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.summary-card-value {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-main);
  line-height: 1.2;
}

.summary-card-sub {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* チャートセクション */
.chart-section {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.chart-controls {
  display: flex;
  align-items: center;
  gap: 16px;
}

.toggle-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-main);
  cursor: pointer;
  user-select: none;
}

.toggle-label input[type="checkbox"] {
  appearance: none;
  width: 40px;
  height: 22px;
  background-color: #cbd5e1;
  border-radius: 9999px;
  position: relative;
  outline: none;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.toggle-label input[type="checkbox"]:checked {
  background-color: var(--target-color);
}

.toggle-label input[type="checkbox"]::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 18px;
  height: 18px;
  background-color: #ffffff;
  border-radius: 50%;
  transition: transform 0.2s ease;
  box-shadow: var(--shadow-sm);
}

.toggle-label input[type="checkbox"]:checked::after {
  transform: translateX(18px);
}

.chart-wrapper {
  width: 100%;
  height: 380px;
  position: relative;
}

/* データエディターセクション */
.editor-section {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.editor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.editor-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

/* ボタン */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  user-select: none;
  min-height: 38px;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--secondary-bg);
  color: var(--secondary-color);
  border-color: var(--border-color);
}

.btn-secondary:hover {
  background-color: #e2e8f0;
  color: var(--secondary-hover);
}

/* 月別カードグリッド (12ヶ月) */
.month-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 14px;
}

.month-card {
  background: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.month-card:focus-within {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.month-label {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.sales-input-wrapper {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sales-input {
  width: 100%;
  padding: 6px 8px;
  font-size: 0.95rem;
  font-weight: 600;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: #ffffff;
  color: var(--text-main);
  text-align: right;
  outline: none;
  transition: border-color 0.15s ease;
}

.sales-input:focus {
  border-color: var(--border-focus);
}

.unit-label {
  font-size: 0.8125rem;
  color: var(--text-muted);
  white-space: nowrap;
}

.slider-input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: #cbd5e1;
  outline: none;
  cursor: pointer;
  margin: 4px 0 2px;
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: transform 0.1s ease, background-color 0.1s ease;
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--primary-hover);
}

.slider-input::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  border: none;
  box-shadow: var(--shadow-sm);
  transition: transform 0.1s ease, background-color 0.1s ease;
}

.slider-input::-moz-range-thumb:hover {
  transform: scale(1.15);
  background: var(--primary-hover);
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .app-container {
    padding: 16px 12px 48px;
    gap: 18px;
  }

  .title {
    font-size: 1.4rem;
  }

  .chart-wrapper {
    height: 300px;
  }

  .month-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .editor-actions {
    width: 100%;
  }

  .editor-actions .btn {
    flex: 1;
  }
}

@media (max-width: 480px) {
  .summary-grid {
    grid-template-columns: 1fr;
  }

  .month-grid {
    grid-template-columns: 1fr;
  }
}

export interface MonthlySales {
  id: number;
  month: string;
  sales: number;
  target: number;
}

export interface SalesSummaryProps {
  data: MonthlySales[];
}

export interface SalesChartProps {
  data: MonthlySales[];
  showTarget: boolean;
}

export interface DataEditorProps {
  data: MonthlySales[];
  onUpdateSales: (id: number, newSales: number) => void;
  onResetData: () => void;
  onRandomizeData: () => void;
}

import { useMemo } from 'react';
import { SalesSummaryProps } from '../types';

const SalesSummary = ({ data = [] }: SalesSummaryProps) => {
  const summary = useMemo(() => {
    if (data.length === 0) {
      return {
        totalSales: 0,
        averageSales: 0,
        bestMonth: '-',
        bestSales: 0,
        achievedCount: 0,
        totalTarget: 0,
      };
    }

    const totalSales = data.reduce((acc, cur) => acc + cur.sales, 0);
    const totalTarget = data.reduce((acc, cur) => acc + cur.target, 0);
    const averageSales = Math.round(totalSales / data.length);

    let bestMonth = data[0].month;
    let bestSales = data[0].sales;
    let achievedCount = 0;

    data.forEach((item) => {
      if (item.sales > bestSales) {
        bestSales = item.sales;
        bestMonth = item.month;
      }
      if (item.sales >= item.target) {
        achievedCount += 1;
      }
    });

    return {
      totalSales,
      averageSales,
      bestMonth,
      bestSales,
      achievedCount,
      totalTarget,
    };
  }, [data]);

  const achievementRate = summary.totalTarget > 0
    ? Math.round((summary.totalSales / summary.totalTarget) * 100)
    : 0;

  return (
    <div className="summary-grid">
      <div className="summary-card">
        <span className="summary-card-title">年間総売上</span>
        <span className="summary-card-value">{summary.totalSales.toLocaleString()} 万円</span>
        <span className="summary-card-sub">年間目標達成率: {achievementRate}%</span>
      </div>

      <div className="summary-card">
        <span className="summary-card-title">月間平均売上</span>
        <span className="summary-card-value">{summary.averageSales.toLocaleString()} 万円</span>
        <span className="summary-card-sub">12ヶ月間の平均実績</span>
      </div>

      <div className="summary-card">
        <span className="summary-card-title">最高売上月</span>
        <span className="summary-card-value">{summary.bestMonth}</span>
        <span className="summary-card-sub">売上高: {summary.bestSales.toLocaleString()} 万円</span>
      </div>

      <div className="summary-card">
        <span className="summary-card-title">目標達成月数</span>
        <span className="summary-card-value">{summary.achievedCount} / {data.length} ヶ月</span>
        <span className="summary-card-sub">月間目標をクリアした回数</span>
      </div>
    </div>
  );
};

export default SalesSummary;

import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { SalesChartProps } from '../types';

interface SalesChartExtendedProps extends SalesChartProps {
  onToggleTarget?: () => void;
}

const SalesChart = ({
  data = [],
  showTarget = false,
  onToggleTarget,
}: SalesChartExtendedProps) => {
  return (
    <section className="chart-section">
      <div className="chart-header">
        <h2 className="title" style={{ fontSize: '1.25rem' }}>月別売上推移グラフ</h2>
        <div className="chart-controls">
          <label className="toggle-label">
            <input
              type="checkbox"
              checked={showTarget}
              onChange={() => onToggleTarget?.()}
            />
            <span>目標値を比較表示</span>
          </label>
        </div>
      </div>

      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={data}
            margin={{ top: 20, right: 30, left: 10, bottom: 10 }}
          >
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
            <XAxis
              dataKey="month"
              tick={{ fill: '#64748b', fontSize: 12 }}
              axisLine={{ stroke: '#cbd5e1' }}
              tickLine={false}
            />
            <YAxis
              tick={{ fill: '#64748b', fontSize: 12 }}
              axisLine={{ stroke: '#cbd5e1' }}
              tickLine={false}
              unit="万"
            />
            <Tooltip
              formatter={(value: number) => [`${value.toLocaleString()} 万円`]}
              contentStyle={{
                backgroundColor: '#ffffff',
                borderRadius: '8px',
                border: '1px solid #e2e8f0',
                boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                fontSize: '12px',
              }}
            />
            <Legend wrapperStyle={{ paddingTop: '10px' }} />
            <Bar
              dataKey="sales"
              name="売上実績"
              fill="#2563eb"
              radius={[4, 4, 0, 0]}
              maxBarSize={45}
            />
            {showTarget && (
              <Bar
                dataKey="target"
                name="目標値"
                fill="#f59e0b"
                radius={[4, 4, 0, 0]}
                maxBarSize={45}
              />
            )}
          </BarChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
};

export default SalesChart;

import { ChangeEvent } from 'react';
import { DataEditorProps } from '../types';

const DataEditor = ({
  data = [],
  onUpdateSales,
  onResetData,
  onRandomizeData,
}: DataEditorProps) => {
  const handleInputChange = (id: number, e: ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value, 10);
    onUpdateSales?.(id, isNaN(val) ? 0 : Math.max(0, Math.min(1000, val)));
  };

  const handleSliderChange = (id: number, e: ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value, 10);
    onUpdateSales?.(id, val);
  };

  return (
    <section className="editor-section">
      <div className="editor-header">
        <h2 className="title" style={{ fontSize: '1.25rem' }}>売上データ編集 (1月〜12月)</h2>
        <div className="editor-actions">
          <button
            type="button"
            className="btn btn-secondary"
            onClick={() => onResetData?.()}
          >
            初期値に戻す
          </button>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => onRandomizeData?.()}
          >
            数値をランダム生成
          </button>
        </div>
      </div>

      <div className="month-grid">
        {data.map((item) => (
          <div key={item.id} className="month-card">
            <div className="month-label">
              <span>{item.month}</span>
              <span className="unit-label">目標: {item.target}万</span>
            </div>

            <div className="sales-input-wrapper">
              <input
                type="number"
                min="0"
                max="1000"
                step="5"
                className="sales-input"
                value={item.sales}
                onChange={(e) => handleInputChange(item.id, e)}
              />
              <span className="unit-label">万円</span>
            </div>

            <input
              type="range"
              min="0"
              max="1000"
              step="5"
              className="slider-input"
              value={item.sales}
              onChange={(e) => handleSliderChange(item.id, e)}
            />
          </div>
        ))}
      </div>
    </section>
  );
};

export default DataEditor;

import { useState } from 'react';
import { MonthlySales } from './types';
import SalesSummary from './components/SalesSummary';
import SalesChart from './components/SalesChart';
import DataEditor from './components/DataEditor';

const INITIAL_SALES_DATA: MonthlySales[] = [
  { id: 1, month: '1月', sales: 420, target: 400 },
  { id: 2, month: '2月', sales: 380, target: 400 },
  { id: 3, month: '3月', sales: 550, target: 500 },
  { id: 4, month: '4月', sales: 480, target: 450 },
  { id: 5, month: '5月', sales: 460, target: 450 },
  { id: 6, month: '6月', sales: 520, target: 500 },
  { id: 7, month: '7月', sales: 590, target: 550 },
  { id: 8, month: '8月', sales: 540, target: 550 },
  { id: 9, month: '9月', sales: 490, target: 480 },
  { id: 10, month: '10月', sales: 610, target: 520 },
  { id: 11, month: '11月', sales: 580, target: 550 },
  { id: 12, month: '12月', sales: 720, target: 650 },
];

const App = () => {
  const [salesData, setSalesData] = useState<MonthlySales[]>(INITIAL_SALES_DATA);
  const [showTarget, setShowTarget] = useState<boolean>(true);

  const handleUpdateSales = (id: number, newSales: number) => {
    setSalesData((prev) =>
      prev.map((item) => (item.id === id ? { ...item, sales: newSales } : item))
    );
  };

  const handleResetData = () => {
    setSalesData(INITIAL_SALES_DATA);
  };

  const handleRandomizeData = () => {
    setSalesData((prev) =>
      prev.map((item) => ({
        ...item,
        sales: Math.floor(Math.random() * 550) + 250,
      }))
    );
  };

  const handleToggleTarget = () => {
    setShowTarget((prev) => !prev);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">月別売上ダッシュボード</h1>
        <p className="subtitle">1月〜12月の売上実績・目標比較および集計サマリー</p>
      </header>

      <SalesSummary data={salesData} />

      <SalesChart
        data={salesData}
        showTarget={showTarget}
        onToggleTarget={handleToggleTarget}
      />

      <DataEditor
        data={salesData}
        onUpdateSales={handleUpdateSales}
        onResetData={handleResetData}
        onRandomizeData={handleRandomizeData}
      />
    </div>
  );
};

export default App;
